glsl:
vec4 effect(vec2 uv) {
  float t = floor(uTime * 10.0);
  vec2 b = floor(uv * vec2(16.0, 9.0));
  float r = hash(b + t);
  vec2 u = uv;
  float on = step(1.0 - uAmount * 0.35, r);
  u.x += (hash(b * 1.7 + t) - 0.5) * 0.2 * on;
  vec3 c = vec3(getColor(u + vec2(0.01 * on, 0.0)).r, getColor(u).g, getColor(u - vec2(0.01 * on, 0.0)).b);
  return vec4(c, getColor(u).a);
}
